'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { getNewsByIdAdmin, updateNews, NewsItem } from '@/lib/supabase'
import ImageUpload from '@/components/ImageUpload'
import { showToast } from '@/components/ui/Toast'
import { use } from 'react'
import { useAdminAuth } from '@/hooks/useAdminAuth'
import LoadingSpinner from '@/components/ui/LoadingSpinner'
import { logger } from '@/lib/utils/logger'

interface EditNewsPageProps {
  params: Promise<{
    id: string
  }>
}

export default function EditNewsPage({ params }: EditNewsPageProps) {
  const { isAdmin, loading: authLoading } = useAdminAuth()
  // Next.js 16'da params artık Promise, React.use() ile unwrap etmeliyiz
  const { id } = use(params)
  
  // TÜM HOOK'LAR ERKEN RETURN'LERDEN ÖNCE ÇAĞRILMALI (React Rules of Hooks)
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    category: '',
    author: '',
    featured: false,
    isTrending: false,
    isDailyNews: false,
    imageUrl: '',
    images: [] as string[],
  })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const router = useRouter()
  const categories = ['Gündem', 'Siyaset', 'Ekonomi', 'Spor', 'Magazin', 'Teknoloji']

  // TÜM HOOK'LAR ERKEN RETURN'LERDEN ÖNCE ÇAĞRILMALI
  useEffect(() => {
    // Admin kontrolü yapılmadan önce hook çağrılmamalı, bu yüzden içeride kontrol ediyoruz
    if (!isAdmin || authLoading) return
    
    const fetchNews = async () => {
      try {
        // Admin için özel fonksiyon kullan - RLS policy'yi bypass eder
        const news = await getNewsByIdAdmin(id)

        if (news) {
          setFormData({
            title: news.title,
            excerpt: news.excerpt || '',
            content: news.content,
            category: news.category,
            author: news.author,
            featured: news.featured,
            imageUrl: news.image_url,
            images: news.images || [],
          })
        } else {
          showToast('Haber bulunamadı!', 'error')
          router.push('/admin/news')
        }
      } catch (error) {
        logger.error('Error fetching news:', error)
        showToast('Haber yüklenirken hata oluştu!', 'error')
      } finally {
        setLoading(false)
      }
    }

    fetchNews()
  }, [id, router, isAdmin, authLoading])

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }))
  }

  const handleImageSelect = (url: string) => {
    if (!formData.imageUrl) {
      // Ana resim yoksa, seçileni ana resim yap
      setFormData(prev => ({ ...prev, imageUrl: url }))
    } else {
      // Ana resim varsa, ek resimler listesine ekle
      setFormData(prev => ({
        ...prev,
        images: [...prev.images, url]
      }))
    }
  }

  const handleRemoveImage = (index: number) => {
    setFormData(prev => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index)
    }))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    // Form validation
    if (!formData.title.trim()) {
      showToast('Lütfen haber başlığı girin!', 'warning')
      return
    }
    if (!formData.content.trim()) {
      showToast('Lütfen haber içeriği girin!', 'warning')
      return
    }
    if (!formData.category) {
      showToast('Lütfen kategori seçin!', 'warning')
      return
    }
    if (formData.excerpt && formData.excerpt.length > 150) {
      showToast('Özet 150 karakterden uzun olamaz!', 'warning')
      return
    }

    setSaving(true)
    try {
      const success = await updateNews(id, {
        title: formData.title,
        excerpt: formData.excerpt,
        content: formData.content,
        category: formData.category,
        author: formData.author,
        featured: formData.featured,
        is_trending: formData.isTrending,
        is_daily_news: formData.isDailyNews,
        image_url: formData.imageUrl,
        images: formData.images,
      })

      if (success) {
        showToast('Haber başarıyla güncellendi!', 'success')
        setTimeout(() => {
          router.push('/admin/news')
        }, 1000)
      } else {
        showToast('Haber güncellenirken hata oluştu!', 'error')
      }
    } catch (error) {
      logger.error('Error updating news:', error)
      showToast('Haber güncellenirken beklenmedik bir hata oluştu!', 'error')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 text-white p-8">
        <div className="max-w-4xl mx-auto">
          <div className="text-center py-16">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
            <p className="mt-4">Haber yükleniyor...</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <Link href="/admin/news" className="text-blue-400 hover:underline mb-4 inline-block">
            ← Haber Yönetimine Dön
          </Link>
          <h1 className="text-3xl font-bold">Haberi Düzenle</h1>
          <p className="text-gray-400 mt-2">Haber bilgilerini güncelleyin</p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="bg-gray-800 rounded-lg p-8 space-y-6">
          {/* Başlık */}
          <div>
            <label htmlFor="title" className="block text-sm font-medium mb-2">
              Başlık *
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
              required
            />
          </div>

          {/* Özet */}
          <div>
            <label htmlFor="excerpt" className="block text-sm font-medium mb-2">
              Özet
            </label>
            <textarea
              id="excerpt"
              name="excerpt"
              value={formData.excerpt}
              onChange={handleInputChange}
              rows={3}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
            />
          </div>

          {/* İçerik */}
          <div>
            <label htmlFor="content" className="block text-sm font-medium mb-2">
              İçerik *
            </label>
            <textarea
              id="content"
              name="content"
              value={formData.content}
              onChange={handleInputChange}
              rows={10}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
              required
            />
          </div>

          {/* Kategori ve Yazar */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label htmlFor="category" className="block text-sm font-medium mb-2">
                Kategori *
              </label>
              <select
                id="category"
                name="category"
                value={formData.category}
                onChange={handleInputChange}
                className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
                required
              >
                <option value="">Kategori Seçin</option>
                {categories.map((category) => (
                  <option key={category} value={category}>
                    {category}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label htmlFor="author" className="block text-sm font-medium mb-2">
                Yazar
              </label>
              <input
                type="text"
                id="author"
                name="author"
                value={formData.author}
                onChange={handleInputChange}
                className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
              />
            </div>
          </div>

          {/* Ana Görsel URL - Eski sistem için fallback */}
          <div>
            <label htmlFor="imageUrl" className="block text-sm font-medium mb-2">
              Ana Görsel URL (Alternatif)
            </label>
            <input
              type="url"
              id="imageUrl"
              name="imageUrl"
              value={formData.imageUrl}
              onChange={handleInputChange}
              className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-white"
              placeholder="https://example.com/image.jpg"
            />
            {formData.imageUrl && (
              <div className="mt-2">
                <img
                  src={formData.imageUrl}
                  alt="Ana görsel"
                  className="w-32 h-24 object-cover rounded-lg"
                />
              </div>
            )}
          </div>

          {/* Modern Resim Yükleme Sistemi */}
          <div>
            <label className="block text-sm font-medium mb-2">
              Resimler (Modern Yükleme Sistemi)
            </label>
            <ImageUpload
              onImageSelect={handleImageSelect}
              currentImages={formData.images}
              onRemoveImage={handleRemoveImage}
              maxImages={10}
            />
          </div>

          {/* Öne Çıkan, Trending ve Günün Haberi */}
          <div className="space-y-3 bg-gray-700 p-4 rounded-lg">
            <div className="flex items-center">
              <input
                type="checkbox"
                id="featured"
                name="featured"
                checked={formData.featured}
                onChange={handleInputChange}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="featured" className="ml-2 block text-sm">
                ⭐ Öne çıkan haber olarak işaretle (Featured)
              </label>
            </div>
            <div className="flex items-center">
              <input
                type="checkbox"
                id="isTrending"
                name="isTrending"
                checked={formData.isTrending}
                onChange={handleInputChange}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="isTrending" className="ml-2 block text-sm">
                🔥 Trend haber olarak göster
              </label>
            </div>
            <div className="flex items-center">
              <input
                type="checkbox"
                id="isDailyNews"
                name="isDailyNews"
                checked={formData.isDailyNews}
                onChange={handleInputChange}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="isDailyNews" className="ml-2 block text-sm">
                📰 Günün haberi olarak göster
              </label>
            </div>
          </div>

          {/* Submit Button */}
          <div className="flex justify-end space-x-4">
            <Link
              href="/admin/news"
              className="px-6 py-3 bg-gray-600 hover:bg-gray-700 rounded-lg font-medium transition"
            >
              İptal
            </Link>
            <button
              type="submit"
              disabled={saving}
              className="px-6 py-3 bg-blue-600 hover:bg-blue-700 rounded-lg font-medium transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {saving ? 'Kaydediliyor...' : 'Güncelle'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}